// Стандарт С++20:

#include <iostream>
#include <format>
#include <array>                                                  // Подключение заголовочного файла для работы с фиксированными контейнерами std::array, которые четко определяют границы массива;
#include <span>                                                   // Подключение заголовочного файла для работы с объектами std::span для работы с безопасными окнами просмотра, которые хранят адрес данных и контролируют границы массива;

namespace
{
    struct antarctica_years_end                                   // Объявление структуры типа antarctica_years_end с инициализацией поля;
    {
            int year{0};
    };
}

int main()
{
    antarctica_years_end so1{.year = 1998};                      // Инициализация переменной типа структуры antarctica_years_end через назначенные инициализаторы (указание поля по имени);
    antarctica_years_end so2{.year = 1999};                      // Инициализация переменной типа структуры antarctica_years_end через назначенные инициализаторы (указание поля по имени);
    antarctica_years_end so3{0};                                 // Инициализация переменной типа структуры antarctica_years_end списком значений (агрегатная инициализация);
    std::array<antarctica_years_end, 3> trio{antarctica_years_end{.year = 2003}}; // Безопасная инициализация массива из 3 элементов с помощью контейнера std::array для определения жестких границ массива через назначенный инициализатор (указание по имени поля типа структуры antarctica_years_end);
    std::cout << std::format("{}\n", trio[0].year);              // Объект cout с помощью оператора << выводит отформатированное значение поля структуры antarctica_years_end через оператор принадлежности;
    const std::array<const antarctica_years_end*, 3> arp{&so1, &so2, &so3}; // Безопасная инициализация массива указаетелей из 3 элементов (указателей) типа структуры antarctica_years_end с помощью контейнера std::array для определения жестких границ массива через агрегатные инициализаторы. Квалификаторы const защищают как массив так и данные, указанные по адресам;
    std::cout << std::format("{}\n", arp[1]->year);                  // Объект cout с помощью оператора << выводит отформатированное значение поля структуры so2 типа antarctica_years_end. Обращаемся ко 2 элементу массива указателя и через оператор членства-указателя получаем доступ к значению поля;
    const std::span<const antarctica_years_end* const> ppa{arp}; // Безопасное наложение взгляда объекта ppa класса std::span на массив типа структуры antarctica_years_end. Объекту ppa записывается адрес первого элемента массива указателей arp. Квалификаторы const полностью защищают от изменений сам объект класса span, указатели внутри него и данные конечных структур;
    auto ppb = ppa;               // Инициализация объекта ppb класса std::span. Объект получает адрес такого же объекта ppa (копия). Тип авто указывает компилятору автоматически применить тип std::span<const antarctica_years_end* const>;
    std::cout << std::format("{}\n",ppa[0]->year);        // Объект cout с помощью оператора << выводит отформатированное значение поля структуры типа antarctica_years_end. Через индекс [0] объекта ppa класса std::span мы получаем доступ к первому указателю на структуру и через оператор членства-указателя получаем доступ к значению поля структуры;
    std::cout << std::format("{}\n",ppa[1]->year);        // Объект cout с помощью оператора << выводит отформатированное значение поля структуры типа antarctica_years_end. Через индекс [1] объекта ppa класса std::span мы получаем доступ ко второму указателю на структуру и через оператор членства-указателя получаем доступ к значению поля структуры;
}



